arguments.command:
kubectl exec -n hotel-reservation deploy/frontend -- sh -c '
echo "=== recommendations body ===";
wget -qO- -T 10 "http://localhost:5000/recommendations?lat=37.7867&lon=-122.4112&inDate=2015-04-09&outDate=2015-04-10" 2>&1; echo "RC=$?"
echo "=== reservation body ===";
wget -qO- -T 10 "http://localhost:5000/reservation?id=1&inDate=2015-04-09&outDate=2015-04-10&lat=37.7867&lon=-122.4112&roomType=King" 2>&1 | head -c 400; echo "RC=$?"' 2>&1 | head -30
echo "=== RESERVATION LOGS ==="; kubectl logs -n hotel-reservation -l io.kompose.service=reservation --tail=40 | tail -25
